#!/usr/bin/env python3
"""Builds nxat/data/win7_missing_apis.json from the win32json metadata (https://github.com/marlersoft/win32json, generated by Microsoft's
win32metadata from the Windows SDK headers): every exported Win32 function whose documented minimum OS is NEWER than Windows 7 SP1.
  usage: build_api_table.py PATH_TO_win32json/api  [OUT.json] [--known-good DIR ...]
--known-good DIR: PE files from software that is KNOWN to run on Windows 7 (e.g. CPython 3.8, Electron 22, PyInstaller 5.13 bootloaders).
Every (dll, function) such binaries import statically is removed from the table: the metadata's "Platform" field is the first documented
platform and is sometimes newer than the real Windows 7 export (e.g. Winsock functions), so real binaries are the ground truth.
Output: {"dll_without_ext_lowercase": {"FunctionName": "windows8.0", ...}, ...}  (only functions with Platform > windows6.1).
Caveat: the 'Platform' field is Microsoft's *documented* minimum; an API that a Windows 7 update (KB) backports is still listed as newer."""
import glob, json, os, re, sys

def ver(p):
    m = re.match(r"windows(\d+)\.(\d+)", p or "")
    return (int(m.group(1)), int(m.group(2))) if m else None

def known_good(dirs):
    import pefile
    good = set()
    for root in dirs:
        for d, _, fs in os.walk(root):
            for f in fs:
                if f.lower().endswith((".exe", ".dll", ".pyd")):
                    try:
                        pe = pefile.PE(os.path.join(d, f), fast_load=False)
                    except pefile.PEFormatError:
                        continue
                    for ent in getattr(pe, "DIRECTORY_ENTRY_IMPORT", []):
                        dll = re.sub(r"\.dll$", "", ent.dll.decode("latin1").lower())
                        for e in ent.imports:
                            if e.name:
                                good.add((dll, e.name.decode()))
                    pe.close()
    return good


def main(api, out, good_dirs=()):
    good = known_good(good_dirs) if good_dirs else set()
    table, total, dropped = {}, 0, 0
    for f in sorted(glob.glob(os.path.join(api, "*.json"))):
        try:
            d = json.load(open(f, encoding="utf-8-sig"))
        except ValueError:
            continue
        for fn in d.get("Functions", []):
            total += 1
            v, dll = ver(fn.get("Platform")), fn.get("DllImport")
            if v and v > (6, 1) and dll:
                key = re.sub(r"\.dll$", "", dll.lower())
                if (key, fn["Name"]) in good:
                    dropped += 1
                    continue
                table.setdefault(key, {})[fn["Name"]] = fn["Platform"]
    json.dump(table, open(out, "w"), sort_keys=True, separators=(",", ":"))
    print("functions scanned: %d; newer than Windows 7: %d in %d DLLs; removed %d that known-good Win7 binaries import -> %s (%d KB)" % (total, sum(len(v) for v in table.values()), len(table), dropped, out, os.path.getsize(out) // 1024))

if __name__ == "__main__":
    a = sys.argv[1:]
    gd = []
    if "--known-good" in a:
        i = a.index("--known-good"); gd = a[i + 1:]; a = a[:i]
    main(a[0], a[1] if len(a) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "nxat", "data", "win7_missing_apis.json"), gd)
